static class Account implements Serializable {
    private static final long serialVersionUID = 1L;
    String id;
    transient String password;         // 안 담긴다
    static String realm = "prod";      // static 도 안 담긴다
    int balance;
    transient int computed = 999;      // transient 인데 초기자가 있다
    transient String tag = "초기자가 넣은 값";
}
